import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k=m[1]; h,w=int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
# define rule: find line rows (dominant != fill, >0.8) and line cols similarly; boxes between adjacent line rows/cols; output color=c if all 4 corner anomalies equal c else fill
def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row); fill=cnt.most_common(1)[0][0]
    # line rows/cols: dominated by one other color with >= 60%
    lin_r=[i for i,row in enumerate(g) if max(Counter(row).values())>=0.6*W and max(Counter(row)).most_common(1)[0][0]!=fill]
    ln_c=[]
    for j in range(W):
        cc=Counter(g[i][j] for i in range(H))
        if cc.most_common(1)[0][1]>=0.6*H and cc.most_common(1)[0][0]!=fill: ln_c.append(j)
    out=[[None]*max(1,len(ln_c)-1) for _ in range(max(1,len(lin_r)-1))]
    for a in range(len(lin_r)-1):
        for b in range(len(ln_c)-1):
            corners=[g[lin_r[a]][ln_c[b]],g[lin_r[a]][ln_c[b+1]],g[lin_r[a+1]][ln_c[b]],g[lin_r[a+1]][ln_c[b+1]]]
            anom=[c for c in corners if c!=fill]
            out[a][b]=anom[0] if len(anom)==4 and anom[0]==anom[3] else fill
    return out
for name in ['Demo pair 1 input','Demo pair 2 input']:
    print(name,'pred:',f(G[name]))
    print('true:', G[f'Demo pair {name.split()[2]} output'])

