from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k=m[1]; h,w=int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
# rule: line rows = rows dominated by one non-fill color, line cols similarly; boxes between adjacent line rows/cols
def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row); fill=cnt.most_common(1)[0][0]
    # line rows: the mode is some other color covering >=60% of the row
    lin_r=[]
    for i,row in enumerate(g):
        cc=Counter(row)
        if cc.most_common(1)[0][0]!=fill and cc.most_common(1)[0][1]>=0.5*W: lin_r.append(i)
    ln_c=[]
    for j in range(W):
        cc=Counter(g[i][j] for i in range(H))
        if cc.most_common(1)[0][0]!=fill and cc.most_common(1)[0][1]>=0.5*H: ln_c.append(j)
    out=[]
    for a in range(len(lin_r)-1):
        rowout=[]
        for b in range(len(ln_c)-1):
            corners=[g[lin_r[a]][ln_c[b]],g[lin_r[a]][ln_c[b+1]],g[lin_r[a+1]][ln_c[b]],g[lin_r[a+1]][ln_c[b+1]]]
            # count corner colors (only when != fill)
            anoms=[c for c in corners if c!=fill]
            if len(anoms)==4 and anoms[0]==anoms[1]==anoms[2]==anoms[3]:
                rowout.append(anoms[0])
            else:
                rowout.append(fill)
        out.append(rowout)
    return out
for name in ['Demo pair 1 input','Demo pair 2 input']:
    p=f(G[name]); t=G[f'Demo pair {name.split()[2]} output']
    print(name,'pred:',p,'\ntrue: ',t, 'match:',p==t)
print('test result:',f(G['Test input']))

