# Hypothesis: for each 2x2 block bounded by line rows/cols:
# - if all 4 corners same -> that color
# - else if any color appears >=3 times -> that color
# - else fill (global most common)
def f(g):
    H,W=len(g),len(g[0]); cts=Counter(v for row in g for v in row); fill=cts.most_common(1)[0][0]
    lin_r=[i for i,row in enumerate(g) if Counter(row).most_common(1)[0][0]!=fill]
    ln_c=[j for j in range(W) if Counter([g[i][j] for i in range(H)]).most_common(1)[0][0]!=fill]
    out=[]
    for a in range(len(lin_r)-1):
        rrow=[]
        for b in range(len(ln_c)-1):
            cs=[g[lin_r[a]][ln_c[b]],g[lin_r[a]][ln_c[b+1]],g[lin_r[a+1]][ln_c[b]],g[lin_r[a+1]][ln_c[b+1]]]
            cnts=Counter(cs)
            if len(set(cs))==1: rrow.append(cs[0])
            elif max(cnts.values())>=3: rrow.append(max(cnts.keys(), key=lambda k:cnts[k]))
            else: rrow.append(fill)
        out.append(rrow)
    return out
